const directory = mkdtempSync(join(tmpdir(), \"stockledger-c19-v5-handoff-recovery-\"));
const workspaceId = \"stockledger-c19-v5-synthetic-handoff-recovery\";
const runAt = new Date(\"2026-09-14T22:00:00.000Z\");
