data.decisions = [];
data.outcomes = [];
data.scannerSettings = { ...data.scannerSettings, universeMode: "frozen_research_universe", frozenUniverseBySector: { XLK: [stock.symbol] } };
const dates = ["2026-09-14"];
while (dates.length < 260) dates.unshift(previousUsTradingDate(dates[0]));
const symbols = [...new Set([stock.symbol, "SPY", "XLK"])];
const histories = symbols.map(symbol => ({ symbol, rows: dates.map((date, index) => ({ symbol, date, open: 100 + index, close: 100 + index, high: 101 + index, low: 99 + index, volume: 1000 })) }));

try {
  const source = new WorkerStore(join(directory, "source.sqlite"));
  source.import(data, 0);
  await runWorker(source, histories, { source: "v5 synthetic recovery fixture", adjustment: "adjusted", now: runAt });
  const sourceBatches = source.workerHandoffBatches(workspaceId);
  const sourceSequence = source.workerHandoffSequence(workspaceId);
  assert.ok(sourceBatches.length > 0, "worker run must create a pending handoff batch");
  const sourceJobs = source.listJobs();
  const sourceOutbox = source.pendingOutbox();
  const sourceLoaded = source.load()!;
  await source.backup(join(directory, "consistent.sqlite"));
  source.close();

  const restored = new WorkerStore(join(directory, "consistent.sqlite"));
  assert.equal(restored.integrityCheck(), true);
  assert.deepEqual(restored.workerHandoffBatches(workspaceId), sourceBatches);
  assert.deepEqual(restored.workerHandoffSequence(workspaceId), sourceSequence);
  assert.deepEqual(restored.listJobs(), sourceJobs);
  assert.deepEqual(restored.pendingOutbox(), sourceOutbox);
  assert.deepEqual(restored.load()!.data.evaluations, sourceLoaded.data.evaluations);
  assert.deepEqual(restored.load()!.data.alerts, sourceLoaded.data.alerts);
  restored.close();

  const decision = { id: "v5-owner-decision", eyeId: eye.id, action: "Entered", note: "Synthetic owner decision", concern: "None", thesisValid: "Yes", timing: "On Time", createdAt: "2026-09-14T23:00:00.000Z", amendments: [{ amendedAt: "2026-09-14T23:10:00.000Z", action: "Revised", note: "Synthetic amendment", concern: "None", thesisValid: "Yes", timing: "On Time" }] };
  data.decisions = [decision];
  data.outcomes = [{ id: "v5-owner-outcome", decisionId: decision.id, reviewWindow: "30d", priceChangeNote: "", maxRunupNote: "", maxDrawdownNote: "", lesson: "Synthetic lesson", recipeSuggestion: "", createdAt: decision.createdAt }];
  const batch = sourceBatches.at(-1)!;
  const generatedAt = batch.createdAt;
  const manifest = makeWorkerHandoffManifest({
    workspaceId, generatedAt, workerRevision: batch.workerRevision, latestSequence: sourceSequence.lastSequence, coverage: "complete",
    scheduler: { state: "healthy", lastInvocationAtUtc: generatedAt, lastSuccessfulRunAtUtc: generatedAt, latestExpectedCompletedSession: "2026-09-14", latestSuccessfulSession: "2026-09-14", missedSessions: [], partialSessions: [], schedulerInstalled: false },
    batches: sourceBatches,
  });
  const applied = applyWorkerHandoff(data, parseWorkerHandoffManifest(JSON.stringify(manifest)), new Date("2026-09-15T00:00:00.000Z"));
  assert.equal(applied.status, "applied");
  const exported = serializeExport(applied.data, 2, new Date("2026-09-15T00:00:00.000Z"));
  const imported = parseExport(exported);
  assert.deepEqual(imported.data.workerAppHandoff, applied.data.workerAppHandoff);
  assert.deepEqual(imported.data.decisions, applied.data.decisions);
  assert.deepEqual(imported.data.outcomes, applied.data.outcomes);
  assert.deepEqual(imported.data.evaluations, applied.data.evaluations);
  assert.deepEqual(imported.data.alerts, applied.data.alerts);
  console.log(JSON.stringify({ synthetic: true, workerSqliteSnapshot: "PASS", integrity: true, pendingHandoffBatchesPreserved: sourceBatches.length, sequencePreserved: sourceSequence, jobsPreserved: sourceJobs.length, pendingOutboxPreserved: sourceOutbox.length, appExportParse: "PASS", appHandoffEvidencePreserved: imported.data.workerAppHandoff?.evidence?.length ?? 0, authoredDecisionsPreserved: imported.data.decisions.length, outcomesPreserved: imported.data.outcomes.length, evaluationsPreserved: imported.data.evaluations?.length ?? 0, alertsPreserved: imported.data.alerts.length }, null, 2));
} finally {
  rmSync(directory, { recursive: true, force: true });
}
TS
